if (!(salary > 0 && socialBase >= 0 && fundBase >= 0) || !isFinite(salary) || !isFinite(socialBase) || !isFinite(fundBase) || !isFinite(special) || special < 0) {
return Result.invalid('social-insurance', '税前工资、社保基数、公积金基数或专项扣除不合法', policy);
}
